import { useState, useRef, useCallback } from "react";
import { useNavigate } from "react-router-dom";
import {
  sendChatMessage,
  getConversation,
  sendFeedback,
} from "../api/chat";
import { escapeCSV } from "../utils/csv";

const ACTION_TO_INTENT = {
  "Handle Missing Values": "handle_missing_values",
  "Remove Outliers": "remove_outliers",
  "Remove Duplicates": "remove_duplicates",
  "Detect Feature Inconsistency": "remove_inconsistencies",
  "Scale Data": "scale_numerical",
  "Encode Data": "encode_categorical",
  "Feature Engineering": "feature_engineering",
};

export default function useChatMessages() {
  const [isLoadingChat, setIsLoadingChat] = useState(false);
  const [chatError, setChatError] = useState("");
  const [pendingFeedback, setPendingFeedback] = useState(false);
  const [submittingFeedback, setSubmittingFeedback] = useState(false);
  const [stepTitle, setStepTitle] = useState("");
  const [selectedActions, setSelectedActions] = useState([]);
  const [inputValue, setInputValue] = useState("");
  const [showHistory, setShowHistory] = useState(false);
  const [historyLogs, setHistoryLogs] = useState([]);

  const chatEndRef = useRef(null);
  const navigate = useNavigate();

  const actions = [
    "Handle Missing Values",
    "Remove Outliers",
    "Remove Duplicates",
    "Detect Feature Inconsistency",
    "Scale Data",
    "Encode Data",
    "Feature Engineering",
  ];

  const cleanError = useCallback((msg) => {
    if (!msg) return "Something went wrong. Please try again.";
    if (msg.includes("does not support image") || msg.includes("Cannot read")) return "Image files are not supported. Please upload a CSV, or Excel file.";
    if (msg.includes("Failed to parse dataset")) return "Could not read the file. Make sure it's a valid CSV, or Excel file.";
    if (msg.includes("Dataset is required")) return "No dataset found. Please upload a file first.";
    if (msg === "SESSION_EXPIRED" || msg.includes("token") || msg.includes("unauthorized") || msg.includes("expired")) return "Your session has expired. Please log out and log in again.";
    return msg;
  }, []);

  const handleSend = useCallback(async ({
    activeChatId,
    currentConversationId,
    headers,
    tableData,
    csvFileName,
    setChats,
    syncConversationId,
    updateFromResponse,
  }) => {
    if (!inputValue.trim() && selectedActions.length === 0) return;

    const thisChatId = activeChatId;
    const thisConvId = currentConversationId;
    const time = new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
    const messageText = inputValue.trim();

    let displayedMessage = messageText;
    if (selectedActions.length > 0) {
      displayedMessage +=
        (displayedMessage ? "\n\n" : "") +
        `Please apply these actions: ${selectedActions.join(", ")}`;
    }

    const userMessage = { sender: "user", text: displayedMessage, time };

    setChats((prev) =>
      prev.map((chat) =>
        chat.id === thisChatId
          ? { ...chat, messages: [...chat.messages, userMessage] }
          : chat
      )
    );

    setInputValue("");
    setChatError("");
    setIsLoadingChat(true);

    try {
      let datasetFile = null;
      if (tableData.length > 0 && headers.length > 0) {
        const csvContent = [
          headers.map(escapeCSV).join(","),
          ...tableData.map((row) => headers.map((h) => escapeCSV(row[h])).join(",")),
        ].join("\n");
        datasetFile = new File([csvContent], csvFileName, { type: "text/csv" });
      }

      const response = await sendChatMessage({
        message: displayedMessage,
        mode: inputValue.trim() === "" && selectedActions.length > 0 ? "manual" : "chat",
        selectedIntents: selectedActions.map((a) => ACTION_TO_INTENT[a] || a),
        conversationId: thisConvId,
        dataset: datasetFile,
      });

      const realConvId = response.conversation_id ?? thisConvId;
      syncConversationId(response.conversation_id, thisChatId);

      const botTime = new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
      setPendingFeedback(!response.finished);
      setStepTitle(response.step_title || "");
      setChats((prev) =>
        prev.map((chat) =>
          chat.id === thisChatId || chat.id === realConvId
            ? {
                ...chat,
                messages: [...chat.messages, { sender: "bot", text: response.assistant_message || "I received your message!", time: botTime, downloadUrl: response.result?.download_url ?? null }],
              }
            : chat
        )
      );

      updateFromResponse(response.result);
      setSelectedActions([]);
    } catch (error) {
      console.error("Chat error:", error);
      setChatError(cleanError(error.message));
      const botTime = new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
      setChats((prev) =>
        prev.map((chat) =>
          chat.id === thisChatId
            ? { ...chat, messages: [...chat.messages, { sender: "bot", text: `Error: ${error.message}`, time: botTime }] }
            : chat
        )
      );
    } finally {
      setIsLoadingChat(false);
    }
  }, [inputValue, selectedActions, cleanError]);

  const handleAutoClean = useCallback(async ({
    uploaded,
    headers,
    tableData,
    csvFileName,
    activeChatId,
    currentConversationId,
    isLoadingChat: loading,
    pendingFeedback: feedback,
    setChats,
    syncConversationId,
    updateFromResponse,
  }) => {
    if (!uploaded) { setChatError("Upload a dataset first"); return; }
    if (loading || feedback) return;

    setChatError("");
    setIsLoadingChat(true);

    const thisChatId = activeChatId;
    const thisConvId = currentConversationId;
    const time = new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });

    setChats((prev) =>
      prev.map((chat) =>
        chat.id === thisChatId
          ? { ...chat, messages: [...chat.messages, { sender: "user", text: "🤖 Auto-clean my dataset", time }] }
          : chat
      )
    );

    try {
      const file = new File(
        [[headers.map(escapeCSV).join(","), ...tableData.map((row) => headers.map((h) => escapeCSV(row[h])).join(","))].join("\n")],
        csvFileName,
        { type: "text/csv" }
      );

      const response = await sendChatMessage({
        message: "🤖 Auto-clean my dataset",
        mode: "full_auto",
        selectedIntents: [],
        conversationId: thisConvId,
        dataset: file,
      });

      const realConvId = response.conversation_id ?? thisConvId;
      syncConversationId(response.conversation_id, thisChatId);

      updateFromResponse(response.result);

      const botTime = new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
      setChats((prev) =>
        prev.map((chat) =>
          chat.id === thisChatId || chat.id === realConvId
            ? { ...chat, messages: [...chat.messages, { sender: "bot", text: response.assistant_message || "✨ Auto-clean completed successfully.", time: botTime, downloadUrl: response.result?.download_url ?? null }] }
            : chat
        )
      );
    } catch (error) {
      console.error(error);
      const friendlyMsg = cleanError(error.message);
      setChatError(friendlyMsg);
      const botTime = new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
      setChats((prev) =>
        prev.map((chat) =>
          chat.id === thisChatId
            ? { ...chat, messages: [...chat.messages, { sender: "bot", text: `❌ ${friendlyMsg}`, time: botTime }] }
            : chat
        )
      );
    } finally {
      setIsLoadingChat(false);
    }
  }, [cleanError]);

  const handleFeedback = useCallback(async ({
    accept,
    currentConversationId,
    submittingFeedback: submitting,
    setChats,
    updateFromResponse,
  }) => {
    if (!currentConversationId || submitting) return;

    setSubmittingFeedback(true);
    setPendingFeedback(false);
    setChatError("");

    try {
      const response = await sendFeedback({ conversationId: currentConversationId, accept });

      const botTime = new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
      setChats((prev) =>
        prev.map((chat) =>
          chat.id === currentConversationId
            ? { ...chat, messages: [...chat.messages, { sender: "bot", text: response.assistant_message, time: botTime, downloadUrl: response.result?.download_url ?? null }] }
            : chat
        )
      );

      setPendingFeedback(!response.finished);
      setStepTitle(response.step_title || "");
      updateFromResponse(response.result);
    } catch (error) {
      console.error("Feedback error:", error);
      setChatError(cleanError(error.message));
    } finally {
      setSubmittingFeedback(false);
    }
  }, [cleanError]);

  const toggleAction = useCallback((action) => {
    setSelectedActions((prev) =>
      prev.includes(action) ? prev.filter((a) => a !== action) : [...prev, action]
    );
  }, []);

  const handleShowHistory = useCallback(async (currentConversationId) => {
    setShowHistory(true);
    setChatError("");
    try {
      let logs = [];
      if (currentConversationId) {
        const data = await getConversation(currentConversationId);
        if (data?.messages) {
          const seen = new Set();
          for (const msg of data.messages) {
            const sender = msg.sender ?? msg.role;
            if ((sender === "assistant" || sender === "bot") && msg.payload?.logs) {
              const time = new Date(msg.created_at).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
              for (const log of msg.payload.logs) {
                if (!seen.has(log) && !log.startsWith("Skipping")) { seen.add(log); logs.push({ message: log, time }); }
              }
            }
          }
        }
      }
      setHistoryLogs(logs);
    } catch (err) {
      console.error("Failed to fetch history logs:", err);
      setChatError("Could not load history");
      setHistoryLogs([]);
    }
  }, [cleanError]);

  const canSend = (uploaded, inputValue, selectedActions) =>
    uploaded && (inputValue.trim() !== "" || selectedActions.length > 0);

  return {
    isLoadingChat, setIsLoadingChat,
    chatError, setChatError,
    pendingFeedback, setPendingFeedback,
    submittingFeedback, setSubmittingFeedback,
    stepTitle, setStepTitle,
    selectedActions, setSelectedActions,
    inputValue, setInputValue,
    showHistory, setShowHistory,
    historyLogs, setHistoryLogs,
    chatEndRef,
    navigate,
    actions,
    cleanError,
    handleSend,
    handleAutoClean,
    handleFeedback,
    toggleAction,
    handleShowHistory,
    canSend,
  };
}
